#include "bsp/native_renderer_record_destroy.hpp"
#include "bsp/native_renderer_container_lifetime.hpp"
#include "bsp/singleton_lifetime.hpp"
#include "native_renderer_record_reference.hpp"
#include <Windows.h>
#include <array>
#include <cstdio>
#include <cstring>
#include <stdexcept>

namespace {
void require(bool condition,const char* message) { if(!condition) throw std::runtime_error(message); }
using Destroy=void (__fastcall*)(void*);
using Reserve=void (__fastcall*)(void*,std::uint32_t,std::int32_t);
struct Header { void* data; std::int32_t count,capacity; };
static_assert(sizeof(Header)==12);
struct Frame { std::uint32_t before; Header header; std::uint32_t after; };
void __cdecl free_original(void* data) noexcept { bsp::singleton_lifetime_free(data); }
struct Spec {
    const char* name;
    const unsigned char* bytes;
    std::size_t length;
    std::uint32_t stride;
    Reserve reserve;
    Destroy destroy;
};
class Original {
    void* code_;
public:
    explicit Original(const Spec& spec):code_(VirtualAlloc(nullptr,spec.length,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE)) {
        require(code_!=nullptr,"VirtualAlloc"); std::memcpy(code_,spec.bytes,spec.length);
        relocate(0x0b,reinterpret_cast<std::uintptr_t>(spec.reserve));
        relocate(0x33,reinterpret_cast<std::uintptr_t>(&free_original));
        DWORD previous;
        require(VirtualProtect(code_,spec.length,PAGE_EXECUTE_READ,&previous)!=0,"VirtualProtect");
        require(FlushInstructionCache(GetCurrentProcess(),code_,spec.length)!=0,"FlushInstructionCache");
    }
    ~Original() { VirtualFree(code_,0,MEM_RELEASE); }
    void relocate(std::size_t site,std::uintptr_t target) {
        auto* code=static_cast<unsigned char*>(code_);
        require(code[site]==0xe8,"CALL operand");
        const auto relative=static_cast<std::uint32_t>(target-reinterpret_cast<std::uintptr_t>(code+site+5));
        std::memcpy(code+site+1,&relative,4);
    }
    Destroy function() const { return reinterpret_cast<Destroy>(code_); }
};
using Outcome=std::array<std::uint32_t,5>;
Outcome run(Destroy destroy,std::uint32_t stride,int scenario) {
    Frame frame{0x13579bdfu,{nullptr,0,0},0x2468ace0u};
    if(scenario!=3) {
        const auto bytes=stride*2;
        frame.header.data=bsp::singleton_lifetime_allocate({bsp::SingletonAllocationKind::object,bytes,bytes});
        std::memset(frame.header.data,0x35,bytes);
        frame.header.count=scenario==0?2:(scenario==1?-3:1);
        frame.header.capacity=scenario==2?-1:2;
    }
    void* const old=frame.header.data;
    destroy(&frame.header);
    require(frame.before==0x13579bdfu&&frame.after==0x2468ace0u,"header guards");
    require(frame.header.count==0,"final count");
    require(frame.header.capacity==(scenario==2?1:(scenario==3?0:2)),"capacity postimage");
    require((frame.header.data==old)==(scenario!=2),"current/stale data pointer");
    // Only compare pointer bits; the backing allocation has been freed.
    return {static_cast<std::uint32_t>(frame.header.count),static_cast<std::uint32_t>(frame.header.capacity),frame.header.data==old,frame.header.data==nullptr,frame.after};
}
void report_runtime_modules() {
    const wchar_t* names[]={L"ucrtbase.dll",L"vcruntime140.dll",L"msvcp140.dll",L"vcruntime140_1.dll"};
    for(const auto* name:names) {
        HMODULE module=GetModuleHandleW(name);
        if(module==nullptr) { std::printf("UNLOADED_RUNTIME|%ls\n",name); continue; }
        wchar_t reported[1024],canonical[1024];
        const auto length=GetModuleFileNameW(module,reported,1024);
        require(length!=0&&length<1024,"loaded module path");
        HANDLE file=CreateFileW(reported,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);
        require(file!=INVALID_HANDLE_VALUE,"loaded module file");
        const auto final_length=GetFinalPathNameByHandleW(file,canonical,1024,FILE_NAME_NORMALIZED);
        CloseHandle(file);
        require(final_length!=0&&final_length<1024,"canonical module file");
        const auto* base=reinterpret_cast<const unsigned char*>(module);
        const auto* dos=reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
        const auto* nt=reinterpret_cast<const IMAGE_NT_HEADERS32*>(base+dos->e_lfanew);
        require(nt->FileHeader.Machine==IMAGE_FILE_MACHINE_I386,"loaded runtime machine");
        std::printf("LOADED_RUNTIME|%ls|%ls|%ls|%04x\n",name,reported,canonical,static_cast<unsigned>(nt->FileHeader.Machine));
    }
}
}
int main() {
    const Spec specs[]={
        {"00b29ba0",original_00b29ba0,sizeof original_00b29ba0,16,&bsp::reserve_native_renderer_records16_00b228b0,&bsp::destroy_native_renderer_records16_00b29ba0},
        {"00b29be0",original_00b29be0,sizeof original_00b29be0,20,&bsp::reserve_native_renderer_records20_00b22940,&bsp::destroy_native_renderer_records20_00b29be0},
        {"00b29c20",original_00b29c20,sizeof original_00b29c20,24,&bsp::reserve_native_renderer_records24_00b229d0,&bsp::destroy_native_renderer_records24_00b29c20},
        {"00b29c60",original_00b29c60,sizeof original_00b29c60,40,&bsp::reserve_native_renderer_records40_00b22a70,&bsp::destroy_native_renderer_records40_00b29c60}
    };
    try {
        for(const auto& spec:specs) {
            Original original(spec);
            for(int scenario=0;scenario<4;++scenario)
                require(run(original.function(),spec.stride,scenario)==run(spec.destroy,spec.stride,scenario),"original/source postimages");
            std::printf("PASS %s: positive/negative count, negative capacity reserve, empty null storage\n",spec.name);
        }
        report_runtime_modules();
        std::puts("PASS: four complete original destructors versus main-archive source; 16 postimage comparisons");
        return 0;
    } catch(const std::exception& error) { std::fprintf(stderr,"FAIL: %s\n",error.what()); return 1; }
}

